Update request-helpers.test.ts by adding two tests to summarizeRequestBody: URLSearchParams with foo=bar has kind urlsearchparams and size params.toString().length; Uint8Array([1,2,3,4]) has kind Uint8Array and size 4.

import { describe, it, expect } from 'vitest';
import { summarizeRequestBody } from './request-helpers';
describe('summarizeRequestBody', () => {
  it('returns arraybuffer kind with size', () => {
    expect(summarizeRequestBody(new ArrayBuffer(8))).toEqual({ kind: 'arraybuffer', size: 8 });
  });
});

